// A word clock: the letters that tell the time lit, the rest faint.
const rows = ['ITLISASAMPM', 'ACQUARTERDC', 'TWENTYFIVEX', 'HALFSTENFTO', 'PASTERUNINE', 'ONESIXTHREE', 'FOURFIVETWO', 'EIGHTELEVEN', 'SEVENTWELVE', 'TENSEOCLOCK']
// "IT IS TWENTY TO THREE": row, first letter, length
const lit = [[0, 0, 2], [0, 3, 2], [2, 0, 6], [3, 9, 2], [5, 6, 5]]
const on = (r, c) => lit.some(([row, start, n]) => row === r && c >= start && c < start + n)

export function get(app) {
  return (
    <div className="flex items-center justify-center bg-neutral-950">
      <div className="grid grid-cols-11 gap-x-3 gap-y-1 font-[Cascadia_Mono]">
        {rows.flatMap((row, r) => row.split('').map((ch, c) => (
          <span className={`text-4xl text-center ${on(r, c) ? 'text-amber-200 font-bold' : 'text-neutral-800'}`}>{ch}</span>
        )))}
      </div>
    </div>
  )
}
